    <div className="table-scroll"><table className="data-table session-table"><thead><tr><th>{t('日期', 'Date')}</th><th>{t('会话 ID', 'Session ID')}</th><th>{t('项目', 'Project')}</th><th>{t('模型', 'Model')}</th><th className="number">Token</th><th className="number">{t('费用参考', 'Est. cost')}</th><th /></tr></thead><tbody>{visible.map((s, i) => <tr key={String(s.id) + s.model + i} onClick={() => setSelected(s)}><td><span className="session-date">{s.date || s.startedAt?.slice(0, 10) || '—'}</span><small className="table-subline">{s.timePrecision === 'day' || !s.startedAt ? t('仅日期', 'Day precision') : timeLabel(s.startedAt, language).split(' ').at(-1)}</small></td><td><button className="session-id" onClick={e => { e.stopPropagation(); setSelected(s); }}>{String(s.id).length > 18 ? String(s.id).slice(0, 8) + '…' + String(s.id).slice(-5) : String(s.id)}<ArrowUpRight size={13} /></button></td><td>{s.project}</td><td><span className="model-name-cell"><i className="model-mark" />{s.model}</span></td><td className="number strong">{compact(s.totalTokens)}</td><td className="number"><Cost value={s.estimatedCost} /></td><td><button className="icon-button" aria-label={t('查看会话详情', 'View session detail')} onClick={e => { e.stopPropagation(); setSelected(s); }}><ChevronRight size={16} /></button></td></tr>)}</tbody></table></div>
    {!rows.length && <EmptyState icon={MessageSquare} title={t('这里暂时没有会话', 'No sessions found')}>{t('调整日期范围或筛选条件，或者更新本机日志。', 'Change the range or filters, or refresh local records.')}</EmptyState>}
